/**
 * Skips Pairip's startup program and restores its obfuscated strings locally.
 *
 * The startup program can trigger the local Play Store paywall. Other VM
 * programs used by app methods are left untouched. Remote license,
 * integrity, and entitlement services are not modified.
 */
@Suppress("unused")
val restoreTempMailPairipStringsPatch = bytecodePatch(
    name = "Restore Temp Mail Pairip Strings (No VM)",
    description = "Restores obfuscated local strings without running Pairip's startup program.",
    default = false,
) {
    compatibleWith(COMPATIBILITY_TEMP_MAIL)

    execute {
        val smali = buildString {
            for ((entry, value, jumbo) in RESTORE_STRING_FIELDS) {
                val opcode = if (jumbo) "const-string/jumbo" else "const-string"
                append(opcode).append(" v0, \"").append(value).append("\"\n")
                append("sput-object v0, ").append(entry).append("\n")
            }
            append("return-void\n")
        }

        PairipStartupLaunchFingerprint.method.addInstructions(0, smali)
    }
}
